dashboard.definition:
{
  "title": "4 · Network Correlation",
  "description": "Correlate Cisco ISE, Catalyst Center (DNA) and switching into one incident timeline.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "bg_001": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "bg_002": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#16A3B0",
        "strokeColor": "#16A3B0",
        "strokeWidth": 1,
        "rx": 3
