  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n13,250\n12,258\n11,233\n10,312\n9,270\n8,281\n7,239\n6,231\n5,228\n4,222\n3,271\n2,290\n1,257\n0,407\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n23,13\n22,16\n21,21\n20,21\n19,18\n18,17\n17,15\n16,14\n15,17\n14,16\n13,13\n12,23\n11,17\n10,17\n9,16\n8,15\n7,17\n6,17\n5,23\n4,24\n3,78\n2,26\n1,22\n0,18\"\n| eval _time=relative_time(now(), \"@h\") - ago*3600\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
